WITH flagged AS (SELECT *, CASE WHEN LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) IS NULL OR reading_ts > LAG(reading_ts) OVER (PARTITION BY device_code ORDER BY reading_ts, id) + INTERVAL 15 MINUTES THEN 1 ELSE 0 END AS new_group_flag FROM device_readings), sessions_device_readings AS (SELECT id, device_code, reading_ts, temp_c, pressure, status_bits, SUM(new_group_flag) OVER (PARTITION BY device_code ORDER BY reading_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS island_id FROM flagged) SELECT id, device_code, temp_c, pressure, island_id FROM sessions_device_readings ORDER BY device_code DESC NULLS LAST
